import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return

    n = int(data[0])

    if n == 0:
        print(-1)
        return

    if len(data) < 1:
        print(-1)
        return

    try:
        arr = list(map(int, data[1:1+n]))
    except (ValueError, IndexError):
        print(-1)
        return

    if len(arr) != n:
        print(-1)
        return

    for num in arr:
        if num < 0:
            print(-1)
            return

    if n == 0:
        print(-1)
        return

    result = []
    for num in arr:
        if num > 0:
            result.append(num)

    if not result:
        print(-1)
        return

    for num in result:
        print(num)

if __name__ == "__main__":
    main()
